  { q: "What is the primary reservoir and transmission vector for Salmonella enterica?", opts: ["Gastrointestinal tract of animals (poultry, cattle, eggs, reptiles) and cross-contaminated produce", "Sterile deep ocean water", "Dry volcanic rocks", "Frozen clean icebergs"], ans: "Gastrointestinal tract of animals (poultry, cattle, eggs, reptiles) and cross-contaminated produce", exp: "Salmonella naturally inhabits intestinal tracts of livestock, poultry, and birds, easily contaminating raw eggs, meat, and crops.", diff: "Easy" },
  { q: "Which anaerobic spore-forming bacterium produces the deadliest neurotoxin known in under-processed low-acid canned food?", opts: ["Clostridium botulinum", "Bacillus cereus", "Lactobacillus acidophilus", "Streptococcus thermophilus"], ans: "Clostridium botulinum", exp: "Clostridium botulinum produces botulinum neurotoxin under anaerobic, low-acid (pH >4.6), high-moisture conditions.", diff: "Easy" },
  { q: "What severe clinical complication can Escherichia coli O157:H7 (STEC) cause in children and the elderly?", opts: ["Hemolytic Uremic Syndrome (HUS), leading to acute renal failure", "Tuberculosis", "Measles", "Bone fractures"], ans: "Hemolytic Uremic Syndrome (HUS), leading to acute renal failure", exp: "Shiga-toxin producing E. coli (STEC) releases potent verotoxins that destroy red blood cells and induce kidney failure (HUS).", diff: "Medium" },
  { q: "What are the two distinct clinical syndromes caused by Bacillus cereus food poisoning?", opts: ["Emetic (vomiting) syndrome and Diarrheal syndrome", "Respiratory and Cardiac syndrome", "Neural and Skin rash syndrome", "Bone and Joint syndrome"], ans: "Emetic (vomiting) syndrome and Diarrheal syndrome", exp: "Bacillus cereus produces a heat-stable emetic toxin in cooked rice and starchy foods, and a heat-labile diarrheal enterotoxin in meats/vegetables.", diff: "Medium" },
  { q: "Why is Staphylococcus aureus enterotoxin particularly hazardous in cooked foods left at room temperature?", opts: ["The enterotoxin is extremely heat-stable and survives normal reheating and boiling temperatures", "It glows in the dark", "It smells like rotten eggs immediately", "It dissolves metal spoons"], ans: "The enterotoxin is extremely heat-stable and survives normal reheating and boiling temperatures", exp: "While S. aureus bacteria are killed by heat, its pre-formed enterotoxin resists boiling for up to 30 minutes.", diff: "Medium" },
  { q: "What is the leading viral cause of foodborne acute gastroenteritis worldwide, often called the 'cruise ship virus'?", opts: ["Norovirus", "Rotavirus", "Hepatitis B", "Influenza A"], ans: "Norovirus", exp: "Norovirus is extremely infectious with an ultra-low infectious dose (<18 viral particles), causing projectile vomiting and diarrhea.", diff: "Easy" },
  { q: "What are the four phases of the bacterial growth curve in order?", opts: ["Lag phase -> Log (exponential) phase -> Stationary phase -> Death phase", "Log phase -> Lag phase -> Death phase -> Birth phase", "Static phase -> Fast phase -> Stop phase -> Run phase", "Death phase -> Sleep phase -> Growth phase -> Peak phase"], ans: "Lag phase -> Log (exponential) phase -> Stationary phase -> Death phase", exp: "Bacteria acclimate in lag, multiply exponentially in log, plateau when nutrients deplete in stationary, and decline in death phase.", diff: "Easy" },
  { q: "Which bacterial pathogen is microaerophilic (requires reduced oxygen levels, ~5% O2) and is a leading cause of poultry enteritis?", opts: ["Campylobacter jejuni", "Pseudomonas aeruginosa", "Bacillus subtilis", "Escherichia coli"], ans: "Campylobacter jejuni", exp: "Campylobacter jejuni thrives in warm, microaerobic environments (42°C, 5% O2, 10% CO2), commonly colonizing chicken gut flora.", diff: "Hard" },
  { q: "What is the difference between Foodborne Infection and Foodborne Intoxication?", opts: ["Infection involves ingesting live pathogens that colonize the gut; Intoxication results from ingesting pre-formed toxins in food", "Infection is mild; intoxication is always fatal", "Infection is caused by viruses; intoxication is caused by alcohol", "There is no scientific difference"], ans: "Infection involves ingesting live pathogens that colonize the gut; Intoxication results from ingesting pre-formed toxins in food", exp: "Infection requires microbial colonization inside host (Salmonella, Listeria); intoxication occurs from pre-formed toxin (C. botulinum, S. aureus).", diff: "Medium" },
  { q: "What is an endospore in food microbiology?", opts: ["A dormant, tough, non-reproductive structure formed by certain bacteria (Bacillus, Clostridium) resistant to heat, drying, and sanitizers", "A mold spore that floats in the air", "A reproductive egg of an intestinal tapeworm", "A viral particle"], ans: "A dormant, tough, non-reproductive structure formed by certain bacteria (Bacillus, Clostridium) resistant to heat, drying, and sanitizers", exp: "Bacterial endospores are survival capsules with high dipicolinic acid and calcium content that withstand boiling water for hours.", diff: "Medium" },
  { q: "Which mycotoxin produced by Aspergillus flavus in peanuts and grains is a potent natural liver carcinogen?", opts: ["Aflatoxin (specifically Aflatoxin B1)", "Ochratoxin A", "Patulin", "Deoxynivalenol (Vomitoxin)"], ans: "Aflatoxin (specifically Aflatoxin B1)", exp: "Aflatoxin B1 is classified as a Group 1 human carcinogen by IARC, targeting hepatocytes and causing hepatocellular carcinoma.", diff: "Hard" },
  { q: "Which fungal mycotoxin is a regulated quality and safety parameter in apple juice?", opts: ["Patulin", "Fumonisin", "Zearalenone", "T-2 Toxin"], ans: "Patulin", exp: "Patulin is produced by Penicillium expansum on rotting apples; standard regulations limit it to 50 parts per billion (ppb) in apple juice.", diff: "Hard" },
  { q: "What parameter does a 'Coliform Count' traditionally indicate in food testing?", opts: ["Sanitary quality and potential fecal contamination during processing or water supply handling", "The exact count of Salmonella", "The presence of botulism toxin", "The amount of protein in food"], ans: "Sanitary quality and potential fecal contamination during processing or water supply handling", exp: "Coliforms and fecal coliforms (E. coli) serve as hygiene indicators pointing to post-processing contamination or inadequate sanitation.", diff: "Medium" },
  { q: "What is the minimum water activity (aw) required for the growth of Staphylococcus aureus under aerobic conditions?", opts: ["0.85 (and can survive down to 0.83 in saline)", "0.99", "0.95", "0.50"], ans: "0.85 (and can survive down to 0.83 in saline)", exp: "S. aureus is remarkably osmotolerant, capable of growing and producing toxins at water activities as low as 0.85.", diff: "Hard" },
  { q: "What is the mechanism of action of bacteriophages when used as food safety biocontrol agents?", opts: ["Viruses that specifically infect, replicate within, and lyse targeted bacterial species (e.g. against Listeria in cheese)", "Bacteria that eat mold cells", "Fungi that ferment sugars into vinegar", "Chemical molecules that dissolve cell walls"], ans: "Viruses that specifically infect, replicate within, and lyse targeted bacterial species (e.g. against Listeria in cheese)", exp: "Host-specific bacteriophages target and kill specific pathogenic bacteria (like Listeria on RTE meats) without affecting beneficial flora.", diff: "Hard" },
  { q: "Which organism is commonly used as a probiotic in fermented dairy products?", opts: ["Lactobacillus acidophilus and Bifidobacterium lactis", "Salmonella enterica", "Pseudomonas fluorescens", "Aspergillus niger"], ans: "Lactobacillus acidophilus and Bifidobacterium lactis", exp: "Lactic acid bacteria (Lactobacillus, Bifidobacterium) promote gastrointestinal barrier integrity and microflora balance.", diff: "Easy" },
  { q: "What causes 'Ropy Milk' or ropiness in bread dough?", opts: ["Slime and exopolysaccharide production by spoilage bacteria such as Alcaligenes or Bacillus subtilis", "Excess sugar in recipes", "Under-baking the bread", "Over-freezing the milk"], ans: "Slime and exopolysaccharide production by spoilage bacteria such as Alcaligenes or Bacillus subtilis", exp: "Spore-formers and psychrotrophs produce long mucilaginous exopolysaccharide capsular threads creating ropiness.", diff: "Medium" },
  { q: "What is the primary food safety hazard associated with consuming raw or undercooked shellfish (oysters)?", opts: ["Vibrio vulnificus, Vibrio parahaemolyticus, and Norovirus", "Clostridium botulinum", "Bacillus cereus", "Trichinella spiralis"], ans: "Vibrio vulnificus, Vibrio parahaemolyticus, and Norovirus", exp: "Filter-feeding bivalves bio-accumulate marine Vibrio species from warm estuarine waters and human norovirus from coastal sewage.", diff: "Medium" },
  { q: "What is Scombroid (Histamine) fish poisoning caused by?", opts: ["Bacterial decarboxylation of free histidine into histamine in temperature-abused scombroid fish (tuna, mackerel, mahi-mahi)", "Puff fish tetrodotoxin", "Ciguatera microalgae toxin", "Heavy metal mercury poisoning"], ans: "Bacterial decarboxylation of free histidine into histamine in temperature-abused scombroid fish (tuna, mackerel, mahi-mahi)", exp: "Spoilage bacteria (Morganella morganii) produce histidine decarboxylase when fish is held above 4°C, accumulating toxic histamine.", diff: "Hard" },
  { q: "What is Ciguatera fish poisoning?", opts: ["Bioaccumulation of ciguatoxins produced by benthic dinoflagellates (Gambierdiscus toxicus) in tropical coral reef fish (barracuda, grouper)", "Eating spoiled canned sardines", "Allergic reaction to fish scales", "Eating farm-raised catfish"], ans: "Bioaccumulation of ciguatoxins produced by benthic dinoflagellates (Gambierdiscus toxicus) in tropical coral reef fish (barracuda, grouper)", exp: "Ciguatoxins bioaccumulate up the food web to apex reef predators; the toxin is heat-stable and odorless.", diff: "Hard" },
  { q: "Which parasite is historically associated with undercooked pork and wild game bear meat?", opts: ["Trichinella spiralis", "Giardia lamblia", "Cryptosporidium parvum", "Anisakis simplex"], ans: "Trichinella spiralis", exp: "Trichinella roundworm larvae encyst in animal striated muscle; freezing or thorough cooking kills the encysted larvae.", diff: "Easy" },
  { q: "Which parasitic nematode is contracted from eating raw or lightly pickled saltwater fish (sushi, ceviche)?", opts: ["Anisakis simplex (herring worm)", "Taenia saginata", "Ascaris lumbricoides", "Enterobius vermicularis"], ans: "Anisakis simplex (herring worm)", exp: "Anisakis larvae burrow into human stomach walls; commercial sushi regulations mandate deep freezing (-20°C for 7 days or -35°C for 15 hours).", diff: "Medium" },
  { q: "What is the Gram stain reaction and morphology of Listeria monocytogenes?", opts: ["Gram-positive, non-spore-forming, short rod (bacillus)", "Gram-negative spiral bacterium", "Gram-positive coccus in clusters", "Gram-negative rod"], ans: "Gram-positive, non-spore-forming, short rod (bacillus)", exp: "Listeria monocytogenes is a Gram-positive facultatively anaerobic non-spore-forming rod displaying tumbling motility at 20-25°C.", diff: "Medium" },
  { q: "What is the Gram stain reaction and morphology of Escherichia coli and Salmonella?", opts: ["Gram-negative, facultatively anaerobic rods (Enterobacteriaceae)", "Gram-positive cocci in chains", "Gram-positive spore-forming rods", "Gram-negative helical cocci"], ans: "Gram-negative, facultatively anaerobic rods (Enterobacteriaceae)", exp: "Both belong to the family Enterobacteriaceae: Gram-negative, oxidase-negative, glucose-fermenting bacilli.", diff: "Easy" },
  { q: "What is an ATP Bioluminescence swab used for in food factory hygiene monitoring?", opts: ["Rapid surface cleanliness testing detecting organic adenosine triphosphate from food residues and microbes within seconds", "Counting individual Salmonella colonies", "Identifying viral RNA sequences", "Testing water pH"], ans: "Rapid surface cleanliness testing detecting organic adenosine triphosphate from food residues and microbes within seconds", exp: "Luciferin-luciferase reaction generates light (Relative Light Units - RLU) proportional to total organic and cellular debris.", diff: "Easy" },
  { q: "Why is traditional culture-based microbial testing being supplemented by real-time PCR in modern food QA labs?", opts: ["PCR amplifies pathogen DNA sequences in hours rather than 3 to 5 days required for traditional agar culture growth", "PCR is performed without laboratory equipment", "PCR works only on dead bacteria", "PCR replaces cooking ovens"], ans: "PCR amplifies pathogen DNA sequences in hours rather than 3 to 5 days required for traditional agar culture growth", exp: "Real-time Polymerase Chain Reaction (qPCR) enables rapid, highly specific screening for Salmonella, Listeria, and STEC within single-shift turnaround.", diff: "Medium" },
  { q: "What is the target pathogen in low-temperature long-time sous-vide processing?", opts: ["Non-proteolytic Clostridium botulinum type B and E spores (able to grow down to 3°C)", "Staphylococcus aureus", "Saccharomyces cerevisiae", "Streptococcus pyogenes"], ans: "Non-proteolytic Clostridium botulinum type B and E spores (able to grow down to 3°C)", exp: "Non-proteolytic C. botulinum spores germinate at chill temperatures under vacuum unless cooked to strict time-temperature regimes.", diff: "Hard" },
  { q: "What is a 'Zero Tolerance' microbiological standard?", opts: ["A regulatory requirement where the detection of any viable pathogen cell in a specified sample volume (e.g. 0 in 25g) renders the food adulterated", "Allowing up to 100 colonies per gram", "Allowing pathogens if food is frozen", "A policy forbidding all food testing"], ans: "A regulatory requirement where the detection of any viable pathogen cell in a specified sample volume (e.g. 0 in 25g) renders the food adulterated", exp: "Zero-tolerance (e.g. for Salmonella or L. monocytogenes in ready-to-eat foods in the US) prohibits any detectable pathogen in 25g samples.", diff: "Medium" },
  { q: "Which foodborne pathogen can cross the placental barrier and cause miscarriages, stillbirths, and fetal meningitis in pregnant women?", opts: ["Listeria monocytogenes", "Campylobacter jejuni", "Shigella flexneri", "Staphylococcus aureus"], ans: "Listeria monocytogenes", exp: "Listeria has unique virulence factors (internalins, listeriolysin O) enabling it to cross mucosal, blood-brain, and placental barriers.", diff: "Easy" }
