async function seedRemainingExams() {
  const connection = await pool.getConnection();
  try {
    console.log('Seeding 30 Questions for all remaining 6 certification exams...');
    await connection.beginTransaction();

    const examsToSeed = [
      { id: 'exam-iso-22000', questions: iso22000Questions, title: 'ISO 22000:2018' },
      { id: 'exam-food-technology', questions: foodTechQuestions, title: 'Food Technology' },
      { id: 'exam-brcgs', questions: brcgsQuestions, title: 'BRCGS' },
      { id: 'exam-fssc-22000', questions: fsscQuestions, title: 'FSSC 22000' },
      { id: 'exam-ghp-gmp', questions: ghpGmpQuestions, title: 'GHP & GMP' },
      { id: 'exam-food-microbiology', questions: microQuestions, title: 'Food Microbiology' }
    ];

    for (const exam of examsToSeed) {
      console.log(`\nProcessing ${exam.title} (${exam.id})...`);
      
      // Clear existing questions for clean seed
      await connection.query('DELETE FROM public_exam_questions WHERE exam_id = ?', [exam.id]);

      // Insert 30 questions
      for (let i = 0; i < exam.questions.length; i++) {
        const q = exam.questions[i];
        const qId = uuidv4();
        await connection.query(`
          INSERT INTO public_exam_questions 
            (id, exam_id, question_text, type, options_json, correct_answer, explanation, marks, order_index, difficulty_level)
          VALUES 
            (?, ?, ?, 'mcq', ?, ?, ?, 1, ?, ?)
        `, [qId, exam.id, q.q, JSON.stringify(q.opts), q.ans, q.exp, i + 1, q.diff]);
      }

      // Ensure exam settings reflect 10 conducted questions, 10 marks total, 5 passing (50%)
      await connection.query(`
        UPDATE public_exams 
        SET total_questions = 10, total_marks = 10, passing_marks = 5, pass_percentage = 50, enable_certificate = 1, enable_proctoring = 1
        WHERE id = ?
      `, [exam.id]);

      console.log(`✔ Added ${exam.questions.length} questions to ${exam.title}. Pool requirement met: 30 / (10 × 3)`);
    }

    await connection.commit();
    console.log('\n======================================================');
    console.log('ALL 8 CERTIFICATION EXAMS SUCCESSFULLY SEEDED WITH 30 QUESTIONS EACH!');
    console.log('Question Bank Pool 3x rule fully fulfilled across all certifications.');
    console.log('======================================================\n');
  } catch (err) {
    await connection.rollback();
    console.error('Failed to seed remaining questions:', err);
  } finally {
    connection.release();
    process.exit(0);
  }
}

seedRemainingExams();

